class BST:
    def insert(self, node, val):
        if node is None:
            return BinaryTreeNode(val)
        if val < node.val:
            node.left = self.insert(node.left, val)
        elif val > node.val:
            node.right = self.insert(node.right, val)
        return node  # duplicate: ignore

    def delete(self, node, val):
        if node is None:
            return None
        if val < node.val:
            node.left = self.delete(node.left, val)
        elif val > node.val:
            node.right = self.delete(node.right, val)
        else:  # found it
            if node.left is None:   # case 1 & 2: 0 or 1 child
                return node.right
            if node.right is None:
                return node.left
            # case 3: two children — replace with in-order successor
            successor = self._min(node.right)
            node.val = successor.val
            node.right = self.delete(node.right, successor.val)
        return node

    def _min(self, node):
        while node.left:
            node = node.left
        return node

from collections import deque

def level_order(root) -> list[list[int]]:
    """Returns values grouped by level."""
    if not root:
        return []
    result = []
    queue = deque([root])
    while queue:
        level_size = len(queue)      # snapshot: nodes at this level
        level_vals = []
        for _ in range(level_size):
            node = queue.popleft()
            level_vals.append(node.val)
            if node.left:  queue.append(node.left)
            if node.right: queue.append(node.right)
        result.append(level_vals)
    return result

