class SegmentTree:
    def __init__(self, arr: list[int]):
        self.n = len(arr)
        self.tree = [0] * (4 * self.n)
        self._build(arr, 0, 0, self.n - 1)

    def _build(self, arr, node, start, end):
        if start == end:
            self.tree[node] = arr[start]
        else:
            mid = (start + end) // 2
            self._build(arr, 2*node+1, start, mid)
            self._build(arr, 2*node+2, mid+1, end)
            self.tree[node] = self.tree[2*node+1] + self.tree[2*node+2]

    def query(self, node, start, end, l, r):
        """Sum of arr[l..r] in O(log n)."""
        if r < start or end < l:      # completely outside
            return 0
        if l <= start and end <= r:   # completely inside
            return self.tree[node]
        mid = (start + end) // 2
        return (self.query(2*node+1, start, mid, l, r) +
                self.query(2*node+2, mid+1, end, l, r))

    def update(self, node, start, end, idx, val):
        """Update arr[idx] = val in O(log n)."""
        if start == end:
            self.tree[node] = val
        else:
            mid = (start + end) // 2
            if idx <= mid:
                self.update(2*node+1, start, mid, idx, val)
            else:
                self.update(2*node+2, mid+1, end, idx, val)
            self.tree[node] = self.tree[2*node+1] + self.tree[2*node+2]

class FenwickTree:
    def __init__(self, n: int):
        self.n = n
        self.tree = [0] * (n + 1)   # 1-indexed

    def update(self, i: int, delta: int) -> None:
        """Add delta to position i. O(log n)."""
        while i <= self.n:
            self.tree[i] += delta
            i += i & (-i)             # move to parent: add lowest set bit

    def prefix_sum(self, i: int) -> int:
        """Sum of elements in [1..i]. O(log n)."""
        total = 0
        while i > 0:
            total += self.tree[i]
            i -= i & (-i)             # move to responsible ancestor: strip lowest set bit
        return total

    def range_sum(self, l: int, r: int) -> int:
        """Sum of elements in [l..r]. O(log n)."""
        return self.prefix_sum(r) - self.prefix_sum(l - 1)

